/* @lc app=leetcode id=3008 lang=kotlin */ class Solution { fun occ(s: String, p: String): List<Int> = (p + '#' + s).let { c -> IntArray(c.length).let { pi -> (1 until c.length).filter { i -> generateSequence(pi[i - 1]) { if (it > 0 && c[it] != c[i]) pi[it - 1] else null }.last().let { k0 -> (if (c[k0] == c[i]) k0 + 1 else k0).also { pi[i] = it } == p.length } }.map { it - 2 * p.length } } } fun lb(a: List<Int>, v: Int): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] < v) m + 1 to hi else lo to m } }.last().first fun beautifulIndices(s: String, a: String, b: String, k: Int): List<Int> = occ(s, a).let { A -> occ(s, b).let { B -> A.filter { i -> lb(B, i - k).let { idx -> idx < B.size && B[idx] <= i + k } } } } }